_LANGUAGE: ContextVar[str] = ContextVar("owbm_language", default="ru")


def normalize_language(language: Optional[str]) -> str:
    return language if language in LANGUAGES else "ru"


def get_language() -> str:
    return _LANGUAGE.get()


def set_language(language: Optional[str]) -> Token:
    """Set the current UI language and return a token for restoring it."""
    return _LANGUAGE.set(normalize_language(language))


def reset_language(token: Token) -> None:
    _LANGUAGE.reset(token)


@contextmanager
def language_context(language: Optional[str]) -> Iterator[None]:
    token = set_language(language)
    try:
        yield
    finally:
        reset_language(token)


class _FormatValues(dict):
    def __missing__(self, key: str) -> str:
        return "{" + key + "}"


def localize_text(text: str, *, language: Optional[str] = None) -> str:
    """Translate a known static/catalog-formatted message, leaving unknown data untouched."""
    locale = normalize_language(language) if language is not None else get_language()
    source_locale = "ru" if locale == "en" else "en"
    candidates = []
    for translations in MESSAGES.values():
        source = translations.get(source_locale)
        target = translations.get(locale)
        if not source or not target:
            continue
        if source == text:
            return target
        if source == target:
            continue
        try:
            parts = list(string.Formatter().parse(source))
        except ValueError:
            continue
        if not any(field for _literal, field, _spec, _conversion in parts):
            continue
        literal_size = sum(len(literal) for literal, _field, _spec, _conversion in parts)
        # Generic templates such as "{path}: {reason}" can match arbitrary
        # user data. Only infer translations from messages with a specific
        # static prefix/suffix; call sites should use tr() for generic formats.
        if literal_size < 8:
            continue
        pattern = "^"
        fields = []
        supported = True
        for literal, field, spec, conversion in parts:
            pattern += re.escape(literal)
            if field is None:
                continue
            if spec or conversion or not field.isidentifier():
                supported = False
                break
            pattern += "(.+?)"
            fields.append(field)
        if supported:
            candidates.append((literal_size, pattern + "$", fields, target))

    for _specificity, pattern, fields, target in sorted(
        candidates, key=lambda item: item[0], reverse=True
    ):
        match = re.fullmatch(pattern, text, flags=re.DOTALL)
        if not match:
            continue
        values = {
            field: localize_text(value, language=locale)
            if field in {"reason", "error", "filesystem"} else value
            for field, value in zip(fields, match.groups())
        }
        try:
            return target.format_map(_FormatValues(values))
        except (ValueError, AttributeError):
            continue
    return text


def tr(message_id: str, *, language: Optional[str] = None, **values: object) -> str:
    """Return a localized message, falling back to Russian if a locale is absent."""
    translations = MESSAGES.get(message_id)
    if translations is None:
        return message_id
    locale = normalize_language(language) if language is not None else get_language()
    template = translations.get(locale) or translations.get("ru") or message_id
    try:
        return template.format_map(_FormatValues(values))
    except (ValueError, AttributeError):
        return template
